function validate([queries, dictionary]) {
  if (queries.length < 1 || queries.length > 100) return 'queries needs 1 to 100 words.';
  if (dictionary.length < 1 || dictionary.length > 100) return 'dictionary needs 1 to 100 words.';
  const n = queries[0].length;
  if (n < 1 || n > 100) return 'Words have 1 to 100 letters.';
  for (const word of [...queries, ...dictionary]) {
    if (word.length !== n) return 'All words must have the same length.';
    if (!/^[a-z]+$/.test(word)) return 'Words use only lowercase English letters.';
  }
  return null;
}

