function twoEditWords(queries, dictionary) {
  const result = [];
  for (const query of queries) {
    for (const word of dictionary) {
      let edits = 0;
      for (let i = 0; i < query.length && edits <= 2; i++) {
        if (query[i] !== word[i]) {
          edits++;
        }
      }
      if (edits <= 2) {
        result.push(query);
        break;
      }
    }
  }
  return result;
}

