function twoEditWords(queries, dictionary) {
  // Mask up to two positions with '*' in every way; two words are within two edits
  // exactly when masking their (at most two) differing positions makes them equal.
  const masks = (word) => {
    const out = [word];
    for (let a = 0; a < word.length; a++) {
      const one = word.slice(0, a) + '*' + word.slice(a + 1);
      out.push(one);
      for (let b = a + 1; b < word.length; b++) out.push(one.slice(0, b) + '*' + one.slice(b + 1));
    }
    return out;
  };
  const known = new Set(dictionary.flatMap(masks));
  return queries.filter(query => masks(query).some(m => known.has(m)));
}

