function generate(rand, size) {
  const small = size === 'small';
  const letters = small ? 'abc'.slice(0, 2 + Math.floor(rand() * 2)) : 'abcdefghijklmnopqrstuvwxyz'.slice(0, 2 + Math.floor(rand() * 4));
  const n = small ? 1 + Math.floor(rand() * 5) : 100;
  const word = () => Array.from({ length: n }, () => letters[Math.floor(rand() * letters.length)]).join('');
  const dictionary = Array.from({ length: small ? 1 + Math.floor(rand() * 4) : 100 }, word);
  // Many queries are dictionary words with a few letters changed, so both answers are common.
  const nearby = () => {
    const chars = dictionary[Math.floor(rand() * dictionary.length)].split('');
    const changes = Math.floor(rand() * 5);
    for (let k = 0; k < changes; k++) chars[Math.floor(rand() * n)] = letters[Math.floor(rand() * letters.length)];
    return chars.join('');
  };
  const queries = Array.from({ length: small ? 1 + Math.floor(rand() * 6) : 100 }, () => rand() < 0.6 ? nearby() : word());
  return [queries, dictionary];
}
